      "serverFunctions.ai.modeAria": "\u0648\u0636\u0639 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0644\u062F\u0627\u0644\u0629 \u0627\u0644\u062E\u0627\u062F\u0645",
      "serverFunctions.ai.noModels": "\u0641\u0639\u0651\u0644 \u0646\u0645\u0648\u0630\u062C \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064A \u064A\u062F\u0639\u0645 \u0627\u0644\u0645\u062D\u0627\u062F\u062B\u0629 \u0641\u064A \u0625\u0639\u062F\u0627\u062F\u0627\u062A AI.",
      "serverFunctions.ai.noSourceApplied": "\u0627\u0644\u0645\u062D\u0631\u0631 \u0644\u0645 \u064A\u062A\u063A\u064A\u0651\u0631 \u2014 \u0647\u0630\u0647 \u0627\u0644\u062C\u0648\u0644\u0629 \u0641\u062D\u0635\u062A \u0641\u0642\u0637 (\u0645\u062B\u0644 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0643\u0648\u062F \u0623\u0648 \u062A\u0634\u063A\u064A\u0644 \u0627\u062E\u062A\u0628\u0627\u0631) \u062F\u0648\u0646 draft \u0644\u0644\u0645\u0635\u062F\u0631. \u0631\u062F \u0628\u0645\u062B\u0644 \xABdraft \u0627\u0644\u0622\u0646\xBB \u0623\u0648 \u0627\u0646\u062A\u0642\u0644 \u0625\u0644\u0649 Ask \u0644\u0627\u0642\u062A\u0631\u0627\u062D patch \u064A\u0645\u0643\u0646\u0643 \u062A\u0637\u0628\u064A\u0642\u0647.",
      "serverFunctions.ai.pendingHint": "\u0631\u0627\u062C\u0639 \u0647\u0630\u0627 \u0627\u0644\u0645\u0635\u062F\u0631\u060C \u062B\u0645 \u0627\u0646\u0642\u0631 Apply. \u0644\u0627 \u064A\u064F\u062D\u0641\u0638 \u0634\u064A\u0621 \u062D\u062A\u0649 \u062A\u0646\u0642\u0631 Save.",
