      "serverFunctions.ai.toolsRequired": "\u0648\u0636\u0639 Agent \u064A\u062D\u062A\u0627\u062C \u0646\u0645\u0648\u0630\u062C\u064B\u0627 \u0628\u0642\u062F\u0631\u0629 Tools. \u0627\u062E\u062A\u0631 \u0648\u0627\u062D\u062F\u064B\u0627 \u0645\u0646 \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0646\u0645\u0627\u0630\u062C\u060C \u0623\u0648 \u0627\u0646\u062A\u0642\u0644 \u0625\u0644\u0649 Ask.",
      "serverFunctions.ai.welcome": "\u0648\u0636\u0639 Ask \u064A\u0642\u062A\u0631\u062D TypeScript \u0644\u0645\u0631\u0627\u062C\u0639\u062A\u0647 \u0648\u062A\u0637\u0628\u064A\u0642\u0647. \u064A\u0634\u063A\u0651\u0644 Agent \u0627\u0644\u062A\u0646\u0641\u064A\u0630\u060C \u064A draft \u0625\u0635\u0644\u0627\u062D\u064B\u0627\u060C \u0648\u064A\u0643\u062A\u0628\u0647 \u0641\u064A \u0627\u0644\u0645\u062D\u0631\u0631 \u2014 \u0644\u0627 \u064A\u064F\u062D\u0641\u0638 \u0634\u064A\u0621 \u062D\u062A\u0649 \u062A\u0646\u0642\u0631 Save.",
      "serverFunctions.builtinRoute": "\u0645\u0633\u0627\u0631 \u0645\u062F\u0645\u062C \u2014 \u0645\u062D\u0645\u064A \u0645\u0646 \u0627\u0644\u062D\u0630\u0641\u061B \u0644\u0627 \u064A\u0645\u0643\u0646 \u062A\u0628\u062F\u064A\u0644\u0647 \u0628\u0639\u062F \u0627\u0644\u0625\u0646\u0634\u0627\u0621",
      "serverFunctions.builtinVmHint": "\u0627\u0644\u0645\u0633\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u062F\u0645\u062C\u0629 \u062A\u0633\u062A\u062E\u062F\u0645 \u0645\u0639\u0627\u0644\u062C\u0627\u062A Express \u0627\u0644\u0623\u0635\u0644\u064A\u0629. \u064A\u064F\u0637\u0628\u0651\u064E\u0642 \u0627\u0644\u0645\u0647\u0644\u0629 \u0648\u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u0645\u0624\u0642\u062A\u0629 \u0639\u0644\u0649 \u0627\u0644\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u062D\u064A\u0629\u061B \u064A\u064F\u0637\u0628\u0651\u064E\u0642 \u0648\u0636\u0639 VM \u0648RAM \u0639\u0646\u062F \u062A\u0634\u063A\u064A\u0644 sandbox \u0641\u064A \u0648\u062D\u062F\u0629 \u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631.",
