// src/domain/hwy/hwyPageContextHelpCatalog.ts
function resolveHwyPageContextHelpSections(pageKey) {
  const key = pageKey.trim();
  if (!key.startsWith("hwy-")) {
    return [];
  }
  if (key === "hwy-business-rules-reference") {
    return [];
  }
  if (key === "hwy-org-membership-transfer") {
    return ["org-membership-transfer"];
  }
  if (key === "hwy-nakhebin") {
    return ["nakhebin-linking"];
  }
  if (key.includes("targhin") || key === "hwy-targhin-requests") {
    return ["targhin"];
  }
  if (key.startsWith("hwy-geo-responsibility")) {
    return ["geo-responsibility-legacy"];
  }
  if (key === "hwy-member-courses-activities-management") {
    return ["courses-approval", "activities-approval"];
  }
  if (key.startsWith("hwy-activities-")) {
    const sections = ["activities-approval"];
    if (key.includes("register")) {
      sections.push("activity-self-announcement");
    }
    return sections;
  }
  if (key.startsWith("hwy-courses-")) {
    return ["courses-approval"];
  }
  if (key.startsWith("hwy-member-dossier")) {
    return ["dossier-edit", "identity-masks", "member-files"];
  }
  if (key.startsWith("hwy-members-") || key === "hwy-members-all") {
    if (key.includes("waited") || key.includes("rejected") || key.includes("marfoozeh")) {
      return ["membership-approval-pipeline"];
    }
    return ["member-list-definitions", "membership-approval-pipeline"];
  }
  if (key.startsWith("hwy-etl")) {
    return [];
  }
  return [];
}
function isHwyPageContextHelpEligible(pageKey) {
  const key = String(pageKey ?? "").trim();
  return key.startsWith("hwy-");
}

