// src/shared/ui/shell/pageGuide/pageGuide.attrs.ts
var PAGE_GUIDE_ATTR = "data-page-guide";
var PAGE_GUIDE_TITLE_ATTR = "data-page-guide-title";
var PAGE_GUIDE_HINT_ATTR = "data-page-guide-hint";
var PAGE_GUIDE_PRIORITY_ATTR = "data-page-guide-priority";
var PAGE_GUIDE_SCOPE_ATTR = "data-page-guide-scope";
var PAGE_GUIDE_TOPIC_ATTR = "data-page-guide-topic";
var PAGE_GUIDE_SURFACE_ATTR = "data-page-guide-surface";
var PAGE_GUIDE_REVEAL_ATTR = "data-page-guide-reveal";
var PAGE_GUIDE_MEMBERS_ATTR = "data-page-guide-members";
var pageGuideProps = (input) => {
  const title = String(input.title ?? "").trim();
  const hint = String(input.hint ?? "").trim();
  if (!title || !hint) return {};
  const props = {
    [PAGE_GUIDE_ATTR]: "",
    [PAGE_GUIDE_TITLE_ATTR]: title,
    [PAGE_GUIDE_HINT_ATTR]: hint,
    [PAGE_GUIDE_PRIORITY_ATTR]: String(input.priority ?? 50)
  };
  if (input.scope) props[PAGE_GUIDE_SCOPE_ATTR] = input.scope;
  const topic = input.topic ?? (input.scope === "chrome" ? "navigation" : "page");
  props[PAGE_GUIDE_TOPIC_ATTR] = topic;
  if (input.surface) props[PAGE_GUIDE_SURFACE_ATTR] = "";
  if (input.reveal) props[PAGE_GUIDE_REVEAL_ATTR] = "click";
  const members = (input.members ?? []).map((name) => String(name ?? "").trim()).filter(Boolean);
  if (members.length) props[PAGE_GUIDE_MEMBERS_ATTR] = members.join("|");
  return props;
};

// src/shared/ui/shell/pageGuide/pageGuideChrome.ts
var pageGuideLocalProps = (title, hint, priority = 50) => pageGuideProps({
  title,
  hint,
  priority,
  scope: "local",
  topic: "page"
});

